    import csv, io
    def parse_amount(raw):
        if raw is None:
            return None
        s = raw.strip()
        if not s:
            return None
        neg = False
        if s.startswith("(") and s.endswith(")"):
            neg = True
            s = s[1:-1].strip()
        sign = 1
        if s.startswith("-"):
            sign = -1
            s = s[1:]
        elif s.startswith("+"):
            s = s[1:]
        s = s.replace("$", "").replace(",", "").strip()
